set-variable.value:
@{         try {             var ticket = context.Request.Headers.GetValueOrDefault("X-Core-Call-Ticket", "");             if (context.Request.Url.Query.Count != 1 || !context.Request.Url.Query.ContainsKey("call_id") || context.Request.Url.Query["call_id"].Length != 1) { return false; }
            var callId = context.Request.Url.Query["call_id"][0];             if (ticket.Length > 4096 || !System.Text.RegularExpressions.Regex.IsMatch(callId, @"^[A-Za-z0-9_-]{1,160}$")) { return false; }             var parts = ticket.Split('.');             if (parts.Length != 2) { return false; }             var key = System.Text.Encoding.UTF8.GetBytes("{{core-realtime-ticket-key}}");             string expected;             using (var hmac = new System.Security.Cryptography.HMACSHA256(key)) {                 expected = Convert.ToBase64String(hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(parts[0]))).TrimEnd('=').Replace('+', '-').Replace('/', '_');             }             if (expected.Length != parts[1].Length) { return false; }             var difference = 0;             for (var i = 0; i < expected.Length; i++) { difference |= expected[i] ^ parts[1][i]; }             if (difference != 0) { return false; }             var encoded = parts[0].Replace('-', '+').Replace('_', '/');             encoded += new string('=', (4 - encoded.Length % 4) % 4);             var payload = Newtonsoft.Json.Linq.JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(encoded)));             var decision = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["gatewayDecision"]);             var settings = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["gatewayOperationConstraint"]);             /* APIMが検証した購読を所有者に使い、追加の本人tokenでは所有権を変更しません。 */
            if (context.Subscription == null || String.IsNullOrWhiteSpace(context.Subscription.Id)
                || (bool?)decision["allowed"] != true || (string)decision["method"] != "subscriptionKey"
                || (string)decision["callerId"] != "subscription:" + context.Subscription.Id) { return false; }
            var subscriptionId = context.Subscription.Id;
            var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();             return (int?)payload["v"] == 3 && (string)payload["callId"] == callId
                && (string)payload["subscriptionId"] == subscriptionId                 && (string)payload["callerId"] == (string)decision["callerId"]                                  && (long?)payload["exp"] > now && (long?)payload["exp"] <= now + (int)settings["sessionTtlSeconds"];         } catch { return false; }     }
